import{_ as t,o as r,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科学日报 · 2026-10-09（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-09.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-09.md"}'),i={name:"topics/ai-system-architecture/science-daily-2026-10-09.md"};function n(a,o,l,c,g,u){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-09-ai-系统架构" tabindex="-1">科学日报 · 2026-10-09（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-09-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-09（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> — 第32期 ｜ AI前沿 5 篇</p></blockquote><hr><h2 id="_1-用-ai-驱动的形式化证明搜索推进数学研究-science" tabindex="-1">1. 用 AI 驱动的形式化证明搜索推进数学研究（Science） <a class="header-anchor" href="#_1-用-ai-驱动的形式化证明搜索推进数学研究-science" aria-label="Permalink to &quot;1. 用 AI 驱动的形式化证明搜索推进数学研究（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ DOI: 10.1126/science.aej2213</p></blockquote><ul><li>问题：LLM 数学能力渐强，但<strong>不可靠</strong>限制了其在数学研究中的实用性。</li><li>方法：让 LLM 用 <strong>Lean 等形式化语言</strong>生成证明，由<strong>编译器逐步验证</strong>每一步——构建一个用于<strong>形式化证明搜索的 AI Agent</strong>。</li><li>结果（首次大规模展示价值）：自主解决 353 个 <strong>Erdős 开放问题</strong>中的 <strong>9 个</strong>；证明 OEIS（整数序列在线百科）<strong>492 个猜想中的 44 个</strong>；部署于组合学、优化、图论、代数几何、量子光学研究。<strong>即使是最基础的&quot;LLM 生成 + Lean 验证&quot;交替 Agent 也复现了 Erdős 成果</strong>。</li><li>意义：形式化证明搜索是<strong>自主数学发现</strong>的使能技术——把&quot;正确性&quot;外包给编译器，绕开 LLM 的不可靠。</li><li>洞察：<strong>用形式验证给生成式模型&quot;上保险&quot;</strong>，是本库&quot;AI 自进化/RSI&quot;主线的关键使能件。</li></ul><h2 id="_2-在-rlvr-中把探索与优化解耦-expdis-arxiv" tabindex="-1">2. 在 RLVR 中把探索与优化解耦（ExpDis）（arXiv） <a class="header-anchor" href="#_2-在-rlvr-中把探索与优化解耦-expdis-arxiv" aria-label="Permalink to &quot;2. 在 RLVR 中把探索与优化解耦（ExpDis）（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ arXiv: 2610.10536</p></blockquote><ul><li>问题：可验证奖励 RL（RLVR）承诺&quot;发现新推理策略&quot;，但强加<strong>新颖性激励</strong>收效有限、甚至损害质量；且可验证奖励只监督知识与行为的<strong>一小片</strong>，退化难以恢复。</li><li>方法：<strong>Exploration-Distillation（ExpDis）</strong>——先带新颖性奖励的&quot;探索者&quot;采样，对轨迹做<strong>正确性+质量过滤</strong>，再蒸馏进<strong>不带新颖性奖励的&quot;学生&quot;</strong>，交替多轮。解耦让探索可激进放大而不伤学生。</li><li>结果：七个数学推理基准、两个模型家族上，相同墙钟预算下<strong>优于 DAPO</strong>，并改善 <strong>pass@k 扩展性</strong>。</li><li>洞察：<strong>&quot;探索&quot;与&quot;优化&quot;用不同策略、不同奖励</strong>——把两种目标分开承载，而非硬塞进同一目标函数。可迁移到 Agent 训练与自进化设计。</li></ul><h2 id="_3-robojepa-把机器人潜世界模型-规模化-arxiv" tabindex="-1">3. RoboJEPA：把机器人潜世界模型&quot;规模化&quot;（arXiv） <a class="header-anchor" href="#_3-robojepa-把机器人潜世界模型-规模化-arxiv" aria-label="Permalink to &quot;3. RoboJEPA：把机器人潜世界模型&quot;规模化&quot;（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ arXiv: 2610.10515</p></blockquote><ul><li>问题：潜世界模型能预测未来并规划，但**缺乏&quot;能力随规模/数据/算力如何扩展&quot;**的原则性估计，拖慢进展。</li><li>方法：<strong>RoboJEPA</strong>——基于 <strong>JEPA（联合嵌入预测架构）</strong>、在覆盖 <strong>12 种机器人本体</strong>的大规模数据集上训练。</li><li>结果：<strong>&quot;想象误差&quot;（潜空间 rollout 误差）随算力呈二阶幂律</strong> → 可在拟合范围外预测模型质量；下游规划性能随算力可预测提升、且与想象误差强相关（→ 可靠的评估代理）。可<strong>零样本部署</strong>为机器人 Agent，朝单张目标图像规划完成长程任务。据称是<strong>首个面向多本体、真实机器人数据的世界模型扩展律</strong>；8B 为迄今最大 JEPA 预测器。</li><li>洞察：<strong>把&quot;扩展律&quot;这一 LLM 的方法论搬到机器人世界模型</strong>——一旦有可外推的 scaling law，领域就从试错转向工程。</li></ul><h2 id="_4-sciexam-for-enso-ai-agent-能否造出气候模型-arxiv" tabindex="-1">4. SciExam for ENSO：AI Agent 能否造出气候模型？（arXiv） <a class="header-anchor" href="#_4-sciexam-for-enso-ai-agent-能否造出气候模型-arxiv" aria-label="Permalink to &quot;4. SciExam for ENSO：AI Agent 能否造出气候模型？（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ arXiv: 2610.10513</p></blockquote><ul><li>问题：Agent 被要求做<strong>开放式科研</strong>，但现有评测对着<strong>已知答案/评分表/LLM 评审</strong>——无法判断&quot;新模型&quot;是否有效。</li><li>方法：<strong>SciExam for ENSO</strong>——Agent 从<strong>真实观测</strong>出发，构建 ENSO（厄尔尼诺-南方涛动，年际气候变率主导模态）的<strong>低阶随机模型</strong>。6 小时预算内：处理观测 → 写出<strong>自己的诊断量（随后冻结）</strong> → 仅凭这些诊断量反馈建模；<strong>隐藏评分器</strong>检验：能否重现 ENSO 统计量、恢复未观测变量、预测留出年份——并对一个<strong>已发表模型</strong>用同样方式打分。</li><li>结果：12 个 Agent 系统中 <strong>6 个得分高于已发表模型</strong>（主要靠更好的重构与预报）；更强模型的简化形式还与 <strong>ENSO 冷暖不对称性</strong>两派竞争解释之一自洽——<strong>而该争论任务从未提及</strong>。受控实验表明得分<strong>非来自记忆数据集</strong>，而受所接收信息塑造。</li><li>洞察：<strong>&quot;没有已知答案时也能考 Agent&quot;</strong>——用&quot;对标已发表基线 + 隐藏变量恢复 + 留出预测&quot;构成可验证标尺。且已观察到大模型：<strong>能自主收敛到文献中真实存在的科学争论的一方</strong>——是科研 Agent 涌现能力的强信号。</li></ul><h2 id="_5-phrbench-给-llm-的-幻觉后推理-做行为化评测-arxiv" tabindex="-1">5. PHRBench：给 LLM 的&quot;幻觉后推理&quot;做行为化评测（arXiv） <a class="header-anchor" href="#_5-phrbench-给-llm-的-幻觉后推理-做行为化评测-arxiv" aria-label="Permalink to &quot;5. PHRBench：给 LLM 的&quot;幻觉后推理&quot;做行为化评测（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ arXiv: 2610.10455</p></blockquote><ul><li>问题：幻觉信息在多阶段 LLM 系统中传播、成为后续推理上下文；既有研究多只看<strong>最终结果</strong>，对&quot;模型在<strong>回复层面</strong>如何处置幻觉前提&quot;理解不足。</li><li>方法：<strong>PHRBench</strong>——覆盖 4 个领域、18 个 LLM 的行为化&quot;幻觉后推理（PHR）&quot;基准。<strong>不依赖最终答案对错</strong>，用<strong>幻觉遵从 / 幻觉回避 / 启发式纠正</strong>三维刻画每条轨迹，定义&quot;<strong>有洞察的轨迹</strong>&quot;=最终到达正确答案的<strong>成功纠正</strong>。</li><li>结果：<strong>4820 个受控实例</strong>上成功恢复仍<strong>相对罕见</strong>，且与轨迹中更频繁的<strong>信念更新</strong>相关；幻觉提示词属性对成功恢复有强预测信号，轻量预测器 <strong>AUROC 0.847</strong>。</li><li>洞察：<strong>评测维度从&quot;答案&quot;下沉到&quot;过程&quot;</strong>——与 ExpDis/RoboJEPA 的&quot;给过程/内部状态建立可外推的标尺&quot;同构：<strong>可测量的中间量，才是可改进的量</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第32期 AI 板块</p></blockquote><p>关键词：形式化证明搜索、Lean、Erdős 开放问题、OEIS 猜想、编译器验证、自主数学发现；RLVR、探索-优化解耦、ExpDis、新颖性奖励、蒸馏、pass@k；RoboJEPA、JEPA、潜世界模型、想象误差、scaling law、机器人规划；SciExam、ENSO、AI 科研基准、隐藏评分器、留出预测；PHRBench、幻觉后推理、行为化评测、AUROC 关联：<code>topics/ai-system-architecture/liouville-goldbach-astra-claim.md</code>（<strong>同一主题</strong>：AI 声称解决数学难题——本篇给出&quot;形式验证 + 开放问题批量求解&quot;的<strong>可信版本</strong>）、<code>topics/ai-system-architecture/logic-evolution-godel.md</code>（逻辑/证明的机器化）、<code>topics/ai-system-architecture/dream-rsi.md</code>、<code>topics/ai-system-architecture/brain-self-evolution.md</code>（自进化/RSI：形式验证是给自进化上保险的关键件）、<code>topics/ai-system-architecture/science-daily-2026-10-08.md</code>（前一日：Paper2Agent 论文转可靠 Agent 等）</p>',21)])])}const h=t(i,[["render",n]]);export{q as __pageData,h as default};
